<?php
namespace App\Filament\Resources;
use App\Models\ContactEnquiry; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class ContactEnquiryResource extends Resource { protected static ?string $model=ContactEnquiry::class; protected static ?string $navigationGroup='Enquiries'; protected static ?string $navigationIcon='heroicon-o-envelope'; public static function canViewAny():bool{return auth()->user()?->can('requests.view')??false;} public static function getNavigationBadge():?string{return (string)static::getModel()::where('status','new')->count();} public static function form(Form $form):Form{return $form->schema([Forms\Components\TextInput::make('name')->required(),Forms\Components\TextInput::make('email')->email()->required(),Forms\Components\TextInput::make('mobile'),Forms\Components\Select::make('service_id')->relationship('service','name_en'),Forms\Components\Select::make('preferred_language')->options(['en'=>'English','ar'=>'Arabic']),Forms\Components\TextInput::make('subject'),Forms\Components\Textarea::make('message')->required(),Forms\Components\TextInput::make('source_page'),Forms\Components\Select::make('status')->options(['new'=>'New','assigned'=>'Assigned','contacted'=>'Contacted','converted'=>'Converted','spam'=>'Spam','closed'=>'Closed'])->required(),Forms\Components\Select::make('assigned_to')->relationship('assignee','name'),Forms\Components\Textarea::make('internal_notes'),Forms\Components\DateTimePicker::make('contacted_at')]);} public static function table(Table $table):Table{return $table->defaultSort('created_at','desc')->columns([Tables\Columns\TextColumn::make('name')->searchable(),Tables\Columns\TextColumn::make('email')->searchable(),Tables\Columns\TextColumn::make('service.name_en'),Tables\Columns\BadgeColumn::make('status'),Tables\Columns\TextColumn::make('assignee.name'),Tables\Columns\TextColumn::make('created_at')->dateTime()])->filters([Tables\Filters\SelectFilter::make('status')->options(['new'=>'New','assigned'=>'Assigned','contacted'=>'Contacted','converted'=>'Converted','spam'=>'Spam','closed'=>'Closed'])])->actions([Tables\Actions\EditAction::ma